// ==============================================================================
// HELPER: Google Maps Redirect URL Builder (No API Key Required!)
// ==============================================================================
export function getGoogleMapsUrl(latitude: number, longitude: number, destinationName?: string): string {
  if (destinationName) {
    const encodedDestination = encodeURIComponent(`${destinationName}, ${latitude},${longitude}`)
    return `https://www.google.com/maps/search/?api=1&query=${encodedDestination}`
  }
  return `https://www.google.com/maps?q=${latitude},${longitude}`
}

export function getGoogleMapsDirectionsUrl(latitude: number, longitude: number): string {
  return `https://www.google.com/maps/dir/?api=1&destination=${latitude},${longitude}`
}
